#!/usr/bin/env bash
# This file is auto-generated by @lark-apaas/fullstack-cli
set -euo pipefail

ROOT_DIR="$(pwd)"
DIST_DIR="$ROOT_DIR/dist"

# 记录总开始时间
TOTAL_START=$(node -e "console.log(Date.now())")

# 打印耗时的辅助函数
print_time() {
  local start=$1
  local end=$(node -e "console.log(Date.now())")
  local elapsed=$((end - start))
  local seconds=$((elapsed / 1000))
  local ms=$((elapsed % 1000))
  echo "   ⏱️  耗时: ${seconds}.$(printf "%03d" $ms)s"
}

# ==================== 步骤 0 ====================
echo "🗑️  [0/6] 安装插件"
STEP_START=$(node -e "console.log(Date.now())")
npx fullstack-cli action-plugin init
print_time $STEP_START
echo ""

# ==================== 步骤 1 ====================
echo "📝 [1/6] 更新 openapi 代码"
STEP_START=$(node -e "console.log(Date.now())")
npm run gen:openapi
print_time $STEP_START
echo ""

# 确保 Python 引擎包 engine-bundle.ts 在 nest build 前就位（被 service 静态 import）
ensure_engine_bundle
echo ""

# ==================== 步骤 2 ====================
echo "🗑️  [2/6] 清理 dist 目录"
STEP_START=$(node -e "console.log(Date.now())")
rm -rf "$ROOT_DIR/dist"
print_time $STEP_START
echo ""

# ==================== 步骤 3 ====================
echo "🗺️  [3/6] 生成路由定义"
STEP_START=$(node -e "console.log(Date.now())")

# 在 client/server 构建之前生成到 dist/，供 DefinePlugin 注入前端 bundle
# 注意：nest-cli.json 中 deleteOutDir 必须为 false（模板默认值），否则 nest build 会清掉 dist/
echo "   ├─ 生成 API 路由定义..."
npx generate-api-routes --server-dir ./server --out-dir ./dist > /tmp/gen-api-routes.log 2>&1 &
API_ROUTES_PID=$!

echo "   ├─ 生成页面路由定义..."
npx generate-page-routes --app-path ./client/src/app.tsx --out-dir ./dist > /tmp/gen-page-routes.log 2>&1 &
PAGE_ROUTES_PID=$!

API_ROUTES_EXIT=0
PAGE_ROUTES_EXIT=0

wait $API_ROUTES_PID || API_ROUTES_EXIT=$?
wait $PAGE_ROUTES_PID || PAGE_ROUTES_EXIT=$?

if [ $API_ROUTES_EXIT -ne 0 ]; then
  echo "   ⚠️  API 路由生成失败（不影响构建）"
  cat /tmp/gen-api-routes.log
else
  echo "   ✅ API 路由生成完成"
fi

if [ $PAGE_ROUTES_EXIT -ne 0 ]; then
  echo "   ⚠️  页面路由生成失败（不影响构建）"
  cat /tmp/gen-page-routes.log
else
  echo "   ✅ 页面路由生成完成"
fi
print_time $STEP_START
echo ""

# ==================== 步骤 4 ====================
echo "🔨 [4/6] 并行构建 server 和 client"
STEP_START=$(node -e "console.log(Date.now())")

# 给 server/client 构建子进程预留 8GB heap，缓解 vite build transform 阶段 OOM
# （典型错误：Reached heap limit Allocation failed）。
# 仅在外部未设置 NODE_OPTIONS 时注入，允许 CI / 用户通过外部环境变量完全覆盖
BUILD_NODE_OPTIONS="${NODE_OPTIONS:---max-old-space-size=8192}"

# 根据 only_frontend_change 决定是否构建 server
if [[ "${only_frontend_change:-false}" == "true" ]]; then
  echo "🔨 [4/6] 仅构建 client (only_frontend_change=true)"

  echo "   ├─ 启动 client 构建..."
  NODE_OPTIONS="$BUILD_NODE_OPTIONS" npm run build:client > /tmp/build-client.log 2>&1
  CLIENT_EXIT=$?

  if [ $CLIENT_EXIT -ne 0 ]; then
    echo "   ❌ Client 构建失败"
    cat /tmp/build-client.log
    exit 1
  fi

  echo "   ✅ Client 构建完成"
else
  echo "🔨 [4/6] 并行构建 server 和 client"

  # 并行构建
  echo "   ├─ 启动 server 构建..."
  NODE_OPTIONS="$BUILD_NODE_OPTIONS" npm run build:server > /tmp/build-server.log 2>&1 &
  SERVER_PID=$!

  echo "   ├─ 启动 client 构建..."
  NODE_OPTIONS="$BUILD_NODE_OPTIONS" npm run build:client > /tmp/build-client.log 2>&1 &
  CLIENT_PID=$!

  # 等待两个构建完成
  SERVER_EXIT=0
  CLIENT_EXIT=0

  wait $SERVER_PID || SERVER_EXIT=$?
  wait $CLIENT_PID || CLIENT_EXIT=$?

  # 检查构建结果
  if [ $SERVER_EXIT -ne 0 ]; then
    echo "   ❌ Server 构建失败"
    cat /tmp/build-server.log
    exit 1
  fi

  if [ $CLIENT_EXIT -ne 0 ]; then
    echo "   ❌ Client 构建失败"
    cat /tmp/build-client.log
    exit 1
  fi

  echo "   ✅ Server 构建完成"
  echo "   ✅ Client 构建完成"
fi

print_time $STEP_START
echo ""

# ==================== 步骤 5 ====================
echo "📦 [5/6] 准备产物"
STEP_START=$(node -e "console.log(Date.now())")

# Python Canonical Core 引擎打包（独立于 only_frontend_change，server 构建时必须执行）。
# 经线上诊断确认：① 妙搭部署过滤所有 .py（运行时 /opt/bytefaas 内 py_count=0）；
# ② server/ 只部署 nest 编译“模块依赖图”跟踪的文件，build.sh 后加的孤立 .js 不会上线。
# 因此引擎以 engine-bundle.ts（gzip+base64 常量）入库并被 service 静态 import，
# nest build 会跟踪编译到 dist/server/modules/stock-analysis/engine-bundle.js，随模块部署；
# 运行时 materializeEngine 解压到 /tmp（已确认可写）再 spawn python。Python 仍是唯一算法源。
# 本函数在 nest build 之后核对编译产物；真正的兜底生成在 nest build 之前（见 ensure_engine_bundle）。
bundle_python_engine() {
  local compiled="$DIST_DIR/server/modules/stock-analysis/engine-bundle.js"
  if [ -f "$compiled" ]; then
    echo "   ✅ engine-bundle 随 nest 模块编译 → $compiled（运行时 materialize 解压到 /tmp）"
  else
    echo "   ❌ 未找到编译产物 $compiled；线上形态分析将不可用"
  fi
}

# nest build 之前确保 engine-bundle.ts 存在（正常已入库；缺失则用真实 core 兜底生成）
ensure_engine_bundle() {
  local ts="$ROOT_DIR/server/modules/stock-analysis/engine-bundle.ts"
  if [ ! -f "$ts" ]; then
    if [ -d "$ROOT_DIR/core" ] && [ -f "$ROOT_DIR/python_analyzer.py" ]; then
      echo "   [warn] engine-bundle.ts 缺失，构建前临时生成"
      python3 "$ROOT_DIR/scripts/build_engine_bundle.py" || true
    fi
  fi
  [ -f "$ts" ] && echo "   ✅ engine-bundle.ts 就位" || echo "   ❌ engine-bundle.ts 缺失"
}

# 移动 client 下的 HTML 文件到 dist/dist/client，保证 views 路径在 dev/prod 下一致
# 使用 mv 而非 cp：HTML 不能上传到公网 CDN，移走后 dist/client 中不再包含 HTML
if [ -d "$DIST_DIR/client" ]; then
  mkdir -p "$DIST_DIR/dist/client"
  # public 先进（顶层 client 打包被排除；server setBaseViewsDir + 中间件同源 serve）
  if [ -d "$ROOT_DIR/client/public" ]; then
    cp -R "$ROOT_DIR/client/public/." "$DIST_DIR/dist/client/"
  fi
  # 构建产物 HTML 随后 move，覆盖 public 里的同名文件（保证入口页是构建版，不被 public 静默覆盖）
  find "$DIST_DIR/client" -maxdepth 1 -name "*.html" -exec mv {} "$DIST_DIR/dist/client/" \;
fi

# 引擎归集总是执行（不允许被 only_frontend_change 跳过）
bundle_python_engine

# server 相关产物准备（only_frontend_change=true 时跳过 run.sh/.env）
if [[ "${only_frontend_change:-false}" == "true" ]]; then
  echo "   [skip] 跳过 run.sh/.env 复制 (only_frontend_change=true)"
else
  # 拷贝 run.sh 到 dist/（prod 从 dist/ 启动，确保 cwd 一致性）
  cp "$ROOT_DIR/scripts/run.sh" "$DIST_DIR/"

  # 拷贝 .env 文件（如果存在）
  if [ -f "$ROOT_DIR/.env" ]; then
    cp "$ROOT_DIR/.env" "$DIST_DIR/"
  fi
fi

# 清理无用文件
rm -rf "$DIST_DIR/scripts"
rm -rf "$DIST_DIR/tsconfig.node.tsbuildinfo"

print_time $STEP_START
echo ""

# ==================== 步骤 6 ====================
echo "✂️  [6/6] 智能依赖裁剪"
STEP_START=$(node -e "console.log(Date.now())")

# 智能依赖裁剪（仅全量构建时执行，纯前端场景不打包 server，无需裁剪）
if [[ "${only_frontend_change:-false}" == "true" ]]; then
  echo "✂️  [6/6] 跳过智能依赖裁剪 (only_frontend_change=true)"
else
  echo "✂️  [6/6] 智能依赖裁剪"

  # 分析实际依赖、复制并裁剪 node_modules、生成精简的 package.json
  node "$ROOT_DIR/scripts/prune-smart.js"
fi

print_time $STEP_START
echo ""

# 总耗时
echo "构建完成"
print_time $TOTAL_START

# 输出产物信息
DIST_SIZE=$(du -sh "$DIST_DIR" | cut -f1)
if [[ "${only_frontend_change:-false}" == "true" ]]; then
  echo ""
  echo "📊 构建产物统计:"
  echo "   产物大小:        $DIST_SIZE"
  echo ""
else
  NODE_MODULES_SIZE=$(du -sh "$DIST_DIR/node_modules" | cut -f1)
  echo ""
  echo "📊 构建产物统计:"
  echo "   产物大小:        $DIST_SIZE"
  echo "   node_modules: $NODE_MODULES_SIZE"
  echo ""
fi
